import { Mesh, PlaneGeometry, Object3D, Group, Color, Vector3 } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    MeshStandardNodeMaterial,
    mix,
    uv,
    color,
    float,
    vec3,
    positionWorld,
    varying,
    sprite,
    texture,
    mul,
    add,
    sub,
    pow,
    clamp,
    length,
    step,
    ifThenElse,
    smoothstep,
    fresnel,
    reflect,
    normalWorld,
    dot,
    normalize,
    viewDirection,
    reflectVector,
    clearcoat,
    clearcoatRoughness,
    anisotropy,
    metalness,
    roughness,
    specularColor,
    emissive,
    opacity
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{position: [number, number, number], rotation: [number, number, number], scale: [number, number, number]}} transform
 * @property {{background: string, surface: string, ink: string, paper: string, accent: string, gradientStops: Array<{at:number,hex:string}>}} colors
 * @property {{tier-name: Object, price: Object, caption: Object, feature: Object, 'cta-label': Object}} typography
 * @property {Object} effects
 * @property {Object} textContent
 * @property {Object} assets
 * @property {Array} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader: Function, glbLoader: Function}} loaders
 * @property {{[key:string]: Function}} primitives
 * @property {{fontAtlas: any}} text
 */

/**
 * Helper to create a MSDF text mesh using the provided text utilities.
 * Returns an Object3D positioned at the origin; caller should set position.
 */
function createTextMesh(str, style, ctx) {
    // style: {fontFamily, fontWeight, fontSize, letterSpacing, lineHeight, color}
    // textUtils is expected to expose a method that builds a node‑material mesh.
    // The concrete API may differ; adjust as needed for the real project.
    const textNode = textUtils.createTextNode({
        text: str,
        fontFamily: style.fontFamily,
        fontWeight: style.fontWeight,
        fontSize: style.fontSize,
        letterSpacing: style.letterSpacing,
        lineHeight: style.lineHeight,
        color: style.color,
        // atlas reference is inferred from ctx.text.fontAtlas
        atlas: ctx.text.fontAtlas
    });
    return textNode;
}

/**
 * Build the pricing card.
 */
export default function createNode(config, ctx) {
    /*** PARAMETERS FROM SPEC ***/
    const CARD_WIDTH = 2.4;
    const CARD_HEIGHT = 3.2;
    const CORNER_RADIUS = 0.06;
    const BORDER_THICK = 0.006;
    const HEADER_HEIGHT = 0.08;
    const PADDING = 0.5; // interior padding (scene units)
    const FEATURE_ROW_HEIGHT = 0.375;
    const FEATURE_GAP = 0.006;
    const CTA_WIDTH = 1.4;
    const CTA_HEIGHT = 0.36;
    const CTA_OFFSET_BOTTOM = 0.5;
    const GRAD_TOP = config.colors.gradientStops[0].hex;
    const GRAD_BOTTOM = config.colors.gradientStops[1].hex;

    /*** ROOT OBJECT ***/
    const root = new Object3D();
    const [px, py, pz] = config.transform?.position ?? [0, 0, 0];
    const [rx, ry, rz] = config.transform?.rotation ?? [0, 0, 0];
    const [sx, sy, sz] = config.transform?.scale ?? [1, 1, 1];
    root.position.set(px, py, pz);
    root.rotation.set(rx, ry, rz);
    root.scale.set(sx, sy, sz);
    root.name = 'PricingCard';

    /*** BORDER PLANE (slightly larger) ***/
    const borderGeom = new PlaneGeometry(CARD_WIDTH + 2 * BORDER_THICK, CARD_HEIGHT + 2 * BORDER_THICK);
    const borderMat = new MeshBasicNodeMaterial();
    borderMat.colorNode = color(new Color('#2a2a33'));
    const borderMesh = new Mesh(borderGeom, borderMat);
    borderMesh.name = 'Border';
    root.add(borderMesh);

    /*** CARD BACKGROUND ***/
    const cardGeom = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
    const cardMat = new MeshBasicNodeMaterial();
    cardMat.colorNode = color(new Color(config.colors.surface));
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardMesh.name = 'CardBody';
    root.add(cardMesh);

    /*** HEADER STRIP ***/
    const headerGeom = new PlaneGeometry(CARD_WIDTH, HEADER_HEIGHT);
    const headerMat = new MeshStandardNodeMaterial();
    headerMat.colorNode = color(new Color(config.colors.surface));
    headerMat.metalnessNode = float(0.5);
    headerMat.roughnessNode = float(0.55);
    headerMat.clearcoatNode = float(0.2);
    // Brushed anisotropy approximated via anisotropy node if available
    if (typeof anisotropy !== 'undefined') {
        headerMat.anisotropyNode = float(0.6);
    }
    const headerMesh = new Mesh(headerGeom, headerMat);
    headerMesh.position.set(0, CARD_HEIGHT / 2 - HEADER_HEIGHT / 2, 0.001);
    headerMesh.name = 'HeaderStrip';
    root.add(headerMesh);

    /*** TEXT ELEMENTS ***/
    const texts = [];

    // Tier name
    const tierStyle = {
        fontFamily: config.typography['tier-name'].family,
        fontWeight: config.typography['tier-name'].fontWeight,
        fontSize: config.typography['tier-name'].fontSize,
        letterSpacing: config.typography['tier-name'].letterSpacing,
        lineHeight: config.typography['tier-name'].lineHeight,
        color: config.colors.paper
    };
    const tierMesh = createTextMesh('ATELIER RESERVE', tierStyle, ctx);
    tierMesh.position.set(0, CARD_HEIGHT / 2 - HEADER_HEIGHT - PADDING - tierStyle.fontSize * 0.001, 0.002);
    tierMesh.name = 'TierName';
    texts.push(tierMesh);
    root.add(tierMesh);

    // Price
    const priceStyle = {
        fontFamily: config.typography.price.family,
        fontWeight: config.typography.price.fontWeight,
        fontSize: config.typography.price.fontSize,
        letterSpacing: config.typography.price.letterSpacing,
        lineHeight: config.typography.price.lineHeight,
        color: config.colors.paper
    };
    const priceMesh = createTextMesh('$480', priceStyle, ctx);
    priceMesh.position.set(0, tierMesh.position.y - tierStyle.fontSize * 0.001 - 0.08, 0.002);
    priceMesh.name = 'Price';
    texts.push(priceMesh);
    root.add(priceMesh);

    // Caption (per month)
    const captionStyle = {
        fontFamily: config.typography.caption.family,
        fontWeight: config.typography.caption.fontWeight,
        fontSize: config.typography.caption.fontSize,
        letterSpacing: config.typography.caption.letterSpacing,
        lineHeight: config.typography.caption.lineHeight,
        color: config.colors.paper
    };
    const captionMesh = createTextMesh('PER MONTH, BILLED ANNUALLY', captionStyle, ctx);
    captionMesh.position.set(0, priceMesh.position.y - priceStyle.fontSize * 0.001 - 0.04, 0.002);
    captionMesh.name = 'Caption';
    texts.push(captionMesh);
    root.add(captionMesh);

    // Feature rows
    const featureTexts = [
        'Quarterly movement service',
        'Priority commission slots',
        'Private fitting lounge access',
        'Lifetime case refinishing'
    ];
    const featureStyle = {
        fontFamily: config.typography.feature.family,
        fontWeight: config.typography.feature.fontWeight,
        fontSize: config.typography.feature.fontSize,
        letterSpacing: config.typography.feature.letterSpacing,
        lineHeight: config.typography.feature.lineHeight,
        color: config.colors.paper
    };
    const featureMeshes = [];
    let featureStartY = captionMesh.position.y - captionStyle.fontSize * 0.001 - PADDING;
    for (let i = 0; i < featureTexts.length; i++) {
        const fm = createTextMesh(featureTexts[i], featureStyle, ctx);
        const y = featureStartY - i * (FEATURE_ROW_HEIGHT + FEATURE_GAP);
        fm.position.set(0, y, 0.002);
        fm.name = `Feature${i}`;
        featureMeshes.push(fm);
        root.add(fm);
    }

    // CTA row background
    const ctaGeom = new PlaneGeometry(CTA_WIDTH, CTA_HEIGHT);
    const ctaMat = new MeshBasicNodeMaterial();
    // Gradient using node system
    const vUv = uv();
    const gradColorTop = color(new Color(GRAD_TOP));
    const gradColorBottom = color(new Color(GRAD_BOTTOM));
    ctaMat.colorNode = mix(gradColorTop, gradColorBottom, vUv.y);
    ctaMat.emissiveNode = mix(color(new Color('#000000')), color(new Color(config.colors.accent)), float(1));
    ctaMat.emissiveIntensityNode = float(1.5);
    const ctaMesh = new Mesh(ctaGeom, ctaMat);
    ctaMesh.position.set(0, -CARD_HEIGHT / 2 + CTA_OFFSET_BOTTOM + CTA_HEIGHT / 2, 0.001);
    ctaMesh.name = 'CTABackground';
    root.add(ctaMesh);

    // CTA label
    const ctaLabelStyle = {
        fontFamily: config.typography['cta-label'].family,
        fontWeight: config.typography['cta-label'].fontWeight,
        fontSize: config.typography['cta-label'].fontSize,
        letterSpacing: config.typography['cta-label'].letterSpacing,
        lineHeight: config.typography['cta-label'].lineHeight,
        color: config.colors.paper
    };
    const ctaLabelMesh = createTextMesh('JOIN THE RESERVE', ctaLabelStyle, ctx);
    ctaLabelMesh.position.set(0, ctaMesh.position.y, 0.002);
    ctaLabelMesh.name = 'CTALabel';
    root.add(ctaLabelMesh);
    texts.push(ctaLabelMesh);

    /*** ANIMATIONS ***/
    const timelines = [];

    // Weighted-settle card mount
    const settleTL = gsap.timeline();
    settleTL.from(cardMesh.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)'
    });
    timelines.push(settleTL);

    // Feature rows stagger fade-up
    const featureTL = gsap.timeline({ delay: 0.2 });
    featureMeshes.forEach((fm, idx) => {
        fm.scale.set(1, 1, 1);
        // start invisible and slightly offset
        fm.position.y += 0.2;
        fm.traverse(child => {
            if (child.material && child.material.opacity !== undefined) child.material.transparent = true;
        });
        featureTL.from(
            fm.position,
            {
                y: fm.position.y - 0.2,
                duration: 0.5,
                ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
            },
            idx * 0.08
        );
        featureTL.from(
            fm,
            {
                opacity: 0,
                duration: 0.5,
                ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
            },
            idx * 0.08
        );
    });
    timelines.push(featureTL);

    // CTA press interaction (placeholder – no pointer event, just expose handler)
    const ctaPressHandler = () => {
        gsap.to(ctaMesh.scale, {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            duration: 0.12,
            ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
        });
    };
    root.userData.handlers = {
        'cta-press': ctaPressHandler
    };

    /*** CLEANUP ***/
    root.userData.cleanup = () => {
        timelines.forEach(tl => tl.kill());
        borderGeom.dispose();
        cardGeom.dispose();
        headerGeom.dispose();
        ctaGeom.dispose();
        borderMat.dispose();
        cardMat.dispose();
        headerMat.dispose();
        ctaMat.dispose();
        // Dispose text meshes if they expose dispose
        texts.forEach(t => {
            if (t.geometry) t.geometry.dispose?.();
            if (t.material) t.material.dispose?.();
        });
        featureMeshes.forEach(fm => {
            if (fm.geometry) fm.geometry.dispose?.();
            if (fm.material) fm.material.dispose?.();
        });
    };

    return root;
}
